+      Boolean(await f.policy.purposeConfirmation(f.github, repo, f.pr, [comment(OLD)], hold)),
+      await f.policy.commentConfirms(f.github, repo, f.pr, `/approve-intent ${OLD}`, {exact: true, ...hold})];
